{"path":"outputs/t07_query.sparql","content":"PREFIX geo: <http://www.w3.org/2003/01/geo/wgs84_pos#>
PREFIX schema: <http://schema.org/>
PREFIX wikibase: <http://wikidata.org/entity/>
PREFIX wd: <http://www.wikidata.org/wiki/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>

SELECT ?item ?label ?coordinates
WHERE {
  ?item wdt:P31 wd:Q49807;  # Cultural POI
        wdt:P131 wd:Q11959 . # Located in Alicante (city_qid from config)

  ?item schema:label ?label .

  OPTIONAL {
    ?item geo:name ?coordinates
  }
}
ORDER BY ?item
"}

